def key(r):
 f=r['question'][':question/answer-fields'][0]
 return next(a for a in f[':answer-field/choices'] if a[':answer/id']==f[':answer-field/correct'][1])
def stats(rs):
 groups=collections.defaultdict(list)
 for r in rs:
  f=r['question'][':question/answer-fields'][0];groups[tuple(sorted(a[':answer/value'] for a in f[':answer-field/choices']))].append(r)
 return {'count':len(rs),'targets':dict(collections.Counter(r['generation']['target'] for r in rs)), 'positions':dict(collections.Counter(next(i+1 for i,a in enumerate(r['question'][':question/answer-fields'][0][':answer-field/choices']) if a==key(r)) for r in rs)), 'bank_groups':[{'bank':bank,'count':len(group),'answers':dict(collections.Counter(key(r)[':answer/value'] for r in group))} for bank,group in groups.items()]}
