 for i in range(5):probe('answer position',f+' all','overall',rs,'Always choose position '+str(i+1),lambda r,i=i:r['question'][':question/answer-fields'][0][':answer-field/choices'][i][':answer/value'],'not_predictive','No single position answers this pool.')
