  term={'named':r'\operatorname{Col}(A)','dimensions':r'\dim(\operatorname{Col}(A))','values':r'\mathbb{R}^{n}','adjective':'invertible'}[profile]
  probe('recognizable complete bank',f+'/'+profile,'other_recognizable_subgroup',group,'Ignore blank location; always choose '+term,lambda r,term=term:term,'intended_skill' if profile=='adjective' else 'not_predictive', 'The adjective bank recognizes the one theorem property being taught.' if profile=='adjective' else 'Bank identity cannot reliably determine the answer across its eligible four target locations. Single-observation groups in the five-record batch give no independent evidence of predictiveness; controlled same-bank target changes and fresh delivered controls test that dependency.')
  # Position strategies within each bank, not only aggregate.
