def select(pool,seed,weighted):
 pool=sorted(pool,key=lambda r:r['entity_id'])
 if not pool:return None
 if not weighted:return pool[0]
 d=hashlib.sha256(('course-academy/question-selection/v1/'+seed).encode()).digest();u=(int.from_bytes(d[8:16],'big')>>11)/(1<<53)
 return pool[int(u*len(pool))]
